all_have_both = True
for pos in positions_6_to_6:
    r, c = pos
    has_vert = (r > 0 and input_grid[r-1][c] == 6) or (r < n-1 and input_grid[r+1][c] == 6)
    has_horz = (c > 0 and input_grid[r][c-1] == 6) or (c < m-1 and input_grid[r][c+1] == 6)
    if not (has_vert and has_horz):
        print(f"  FAIL at {pos}: has_vert={has_vert}, has_horz={has_horz}")
        all_have_both = False

if all_have_both:
    print("  ALL 6->6 have BOTH vertical AND horizontal neighbors ✓")

# Now check if ANY 6->3 has both (this would be a false positive)
print("\nChecking if any 6->3 has both vertical AND horizontal neighbors:")
any_fp = False
for pos in positions_6_to_3:
    r, c = pos
    has_vert = (r > 0 and input_grid[r-1][c] == 6) or (r < n-1 and input_grid[r+1][c] == 6)
    has_horz = (c > 0 and input_grid[r][c-1] == 6) or (c < m-1 and input_grid[r][c+1] == 6)
    if has_vert and has_horz:
        any_fp = True
        print(f"  6->3 still has both at {pos}: vert={input_grid[r-1][c] if r>0 else 'NA'}, {input_grid[r+1][c] if r<n-1 else 'NA'}, horz={input_grid[r][c-1] if c>0 else 'NA'}, {input_grid[r][c+1] if c<m-1 else 'NA'}")

if not any_fp:
    print("  No 6->3 has both vertical and horizontal neighbors ✓")

# So the rule might be:
# 6 -> 6 if it has both vertical AND horizontal 6 neighbors
# 6 -> 3 otherwise
# 5 -> 5 always

# Let me apply this rule to predict the output for test input
def predict_output(rule, test_grid):
    n, m = len(test_grid), len(test_grid[0])
    out = [[5 for _ in range(m)] for _ in range(n)]

    for r in range(n):
        for c in range(m):
            if test_grid[r][c] == 5:
                out[r][c] = 5
            else:
                if rule == "both":
                    # 6 stays 6 iff BOTH vertical and horizontal neighbors are 6
                    has_vert = (r > 0 and test_grid[r-1][c] == 6) or (r < n-1 and test_grid[r+1][c] == 6)
                    has_horz = (c > 0 and test_grid[r][c-1] == 6) or (c < m-1 and test_grid[r][c+1] == 6)
                    out[r][c] = 6 if (has_vert and has_horz) else 3
                elif rule == "vertical":
                    # 6 stays 6 iff vertical neighbor is 6
                    has_vert = (r > 0 and test_grid[r-1][c] == 6) or (r < n-1 and test_grid[r+1][c] == 6)
                    out[r][c] = 6 if has_vert else 3
                elif rule == "horizontal":
                    # 6 stays 6 iff horizontal neighbor is 6  
                    has_horz = (c > 0 and test_grid[r][c-1] == 6) or (c < m-1 and test_grid[r][c+1] == 6)
                    out[r][c] = 6 if has_horz else 3

    return out

# Let's also count how many of each we get with the "both" rule
def count_stay_as_6(rule, grid):
    n, m = len(grid), len(grid[0])
    count = 0
    for r in range(n):
        for c in range(m):
            if grid[r][c] == 6:
                if rule == "both":
                    has_vert = (r > 0 and grid[r-1][c] == 6) or (r < n-1 and grid[r+1][c] == 6)
                    has_horz = (c > 0 and grid[r][c-1] == 6) or (c < m-1 and grid[r][c+1] == 6)
                    if has_vert and has_horz:
                        count += 1
                elif rule == "vertical":
                    has_vert = (r > 0 and grid[r-1][c] == 6) or (r < n-1 and grid[r+1][c] == 6)
                    if has_vert:
                        count += 1
                elif rule == "horizontal":
                    has_horz = (c > 0 and grid[r][c-1] == 6) or (c < m-1 and grid[r][c+1] == 6)
                    if has_horz:
                        count += 1
    return count

